/// <reference types="vite/client" />

declare global {
  interface Window {
    // Go bindings generated by Wails from backend/internal/desktop/app.go.
    go?: {
      desktop?: {
        App?: {
          OpenURL(url: string): void;
          PickFolder?(title: string): Promise<string>;
          SaveFile(defaultName: string, content: string): Promise<boolean>;
          RunBuild(runID: string, path: string, script: string): Promise<void>;
        };
      };
    };
    // Wails runtime (the subset Stitch uses).
    runtime?: {
      EventsOn(name: string, callback: (...data: any[]) => void): () => void;
    };
  }
}

export {};
